//! R3 (D12): Laravel's own Validator is the specification of OpenGrid's
//! validation. `validation_spec/cases.txt` lists rules and data; `cases.out`
//! is Laravel 13's answer (generated by `validation_spec/driver.php` with the
//! vendor directory of the Laravel comparison application). Every case must
//! give the same errors, or the same validated data, in OpenGrid.

use std::path::{Path, PathBuf};
use std::sync::Arc;

use opengrid_framework::native::database::surreal::DbConfig;
use opengrid_framework::{Pool, PoolOptions};

fn dir() -> PathBuf {
    Path::new(env!("CARGO_MANIFEST_DIR")).join("tests/validation_spec")
}

/// A PHP single-quoted string literal.
fn quote(s: &str) -> String {
    format!("'{}'", s.replace('\\', "\\\\").replace('\'', "\\'"))
}

#[test]
fn validation_matches_laravel() {
    let root = Path::new(env!("CARGO_MANIFEST_DIR")).join("tests/fixtures/app");
    let pool = Arc::new(Pool::start(PoolOptions::new(root).workers(1).database(DbConfig::mem("test", "validation_spec"))).expect("pool starts"));
    let cases = std::fs::read_to_string(dir().join("cases.txt")).expect("cases");
    let expected = std::fs::read_to_string(dir().join("cases.out")).expect("expected output");
    let cases: Vec<&str> = cases.lines().filter(|l| !l.is_empty() && !l.starts_with('#')).collect();
    let expected: Vec<&str> = expected.lines().collect();
    assert_eq!(cases.len(), expected.len(), "cases.out is out of date: run driver.php");
    let mut failures = Vec::new();
    for (case, want) in cases.iter().zip(&expected) {
        let (rules, data) = case.split_once('\t').expect("rules <TAB> data");
        let src = format!(
            "<?grd\nuse OpenGrid\\Validation\\Validator;\n$data = json_decode({}, true);\n$rules = json_decode({}, true);\n$e = Validator::errors($data, $rules);\necho json_encode(count($e) > 0 ? ['errors' => $e] : ['valid' => Validator::validate($data, $rules)], JSON_UNESCAPED_SLASHES);",
            quote(data),
            quote(rules)
        );
        let got = pool
            .run_sync(move |vm| {
                let r = vm.run_file("t.grd", src.as_bytes());
                let mut out = String::from_utf8_lossy(&vm.output).into_owned();
                if let Err(e) = r {
                    out.push_str(&format!("ERR {e}"));
                }
                vm.reset_request();
                out
            })
            .expect("worker answers");
        let same = match (serde_json::from_str::<serde_json::Value>(&got), serde_json::from_str::<serde_json::Value>(want)) {
            (Ok(a), Ok(b)) => a == b,
            _ => false,
        };
        if !same {
            failures.push(format!("{rules}  {data}\n  laravel:  {want}\n  opengrid: {got}"));
        }
    }
    assert!(failures.is_empty(), "{} of {} cases differ from Laravel:\n{}", failures.len(), cases.len(), failures.join("\n"));
}
